const AVR_DeviceParam* avr_get_device_param(uint16_t i) {
  return i < DEV_IDX_MAX ? &device_params[i] : NULL;
}
int16_t avr_find_device_by_signature(const uint8_t s[3]) {
  for(int16_t i=0; i<DEV_IDX_MAX; i++)
    if(device_params[i].signature[0]==s[0] && device_params[i].signature[1]==s[1])
      return i;
  return -1;
}
int16_t avr_find_device_by_name(const char* n) {
  for(int16_t i=0; i<DEV_IDX_MAX; i++)
    if(strcasecmp(device_names[i], n)==0) return i;
  return -1;
}
const char* avr_get_device_name(uint16_t i) {
  return i < DEV_IDX_MAX ? device_names[i] : NULL;
}